# 计算 v_p(x^n - y^n)
def vp(x):        # 计算 x 中 p 的幂次
  cnt = 0
  while x % p == 0:
    cnt += 1; x //= p
  return cnt

def lte(x, y, n, p):
  # 前提: p 不整除 x 和 y
  if p | (x - y):
    if p == 2 and n % 2 == 0:
      return vp(x-y) + vp(x+y) + vp(n) - 1
    return vp(x-y) + vp(n)
  if p | (x + y) and n % 2 == 1:
    if p == 2 and n == 1: return vp(x+y)
    return vp(x+y) + vp(n)
  return 0

